final_fix = '''import sqlite3
import json

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row

VALID_CABINS = {"business", "economy", "basic_economy", "premium_economy"}
STATUS_MAP = {"active": "available"}
CABIN_MAP = {"first": "business"}

# === FIX ALL FLIGHTS (read all first, then update) ===
rows = list(conn.execute("SELECT flight_id, dates_json, departure_time, arrival_time FROM flights WHERE source_skill='tau2Airline'"))
print(f"Processing {len(rows)} flights...")

for row in rows:
    fid = row["flight_id"]
    dates = json.loads(row["dates_json"] or "{}")
    dep = row["departure_time"] or "08:00:00"
    arr = row["arrival_time"] or "10:00:00"

    for dk, dv in dates.items():
        if not isinstance(dv, dict):
            continue
        # Fix status
        st = dv.get("status", "")
        if st in STATUS_MAP:
            dv["status"] = STATUS_MAP[st]
        # Fix cabin keys
        for field in ["prices", "available_seats"]:
            if field in dv and isinstance(dv[field], dict):
                new_dict = {}
                for cabin, val in dv[field].items():
                    if cabin in VALID_CABINS:
                        new_dict[cabin] = val
                    elif cabin in CABIN_MAP:
                        new_dict[CABIN_MAP[cabin]] = val
                dv[field] = new_dict

    # Always update
    conn.execute(
        "UPDATE flights SET departure_time=?, arrival_time=?, dates_json=? WHERE flight_id=? AND source_skill='tau2Airline'",
        (dep, arr, json.dumps(dates), fid)
    )

# === FIX ALL RESERVATIONS (passenger dob) ===
resv_rows = list(conn.execute("SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill='tau2Airline'"))
print(f"Processing {len(resv_rows)} reservations...")

for row in resv_rows:
    bid = row["booking_id"]
    pax = json.loads(row["passengers_json"] or "[]")
    for p in pax:
        if isinstance(p, dict) and "dob" not in p:
            if "date_of_birth" in p:
                p["dob"] = p["date_of_birth"]
            elif "birth_date" in p:
                p["dob"] = p["birth_date"]
            else:
                p["dob"] = "1990-01-01"
    conn.execute(
        "UPDATE flight_bookings SET passengers_json=? WHERE booking_id=? AND source_skill='tau2Airline'",
        (json.dumps(pax), bid)
    )

conn.commit()

# Verify: check for remaining issues
problems = []
for row in conn.execute("SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline'"):
    dates = json.loads(row["dates_json"] or "{}")
    for dk, dv in dates.items():
        if isinstance(dv, dict):
            st = dv.get("status", "")
            if st not in {"available", "landed", "cancelled", "delayed", "flying", "on time"}:
                problems.append(f"{row['flight_id']}/{dk}: bad status '{st}'")
            for field in ["prices", "available_seats"]:
                if field in dv and isinstance(dv[field], dict):
                    for k in dv[field]:
                        if k not in VALID_CABINS:
                            problems.append(f"{row['flight_id']}/{dk}: bad cabin '{k}' in {field}")

for row in conn.execute("SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill='tau2Airline'"):
    pax = json.loads(row["passengers_json"] or "[]")
    for i, p in enumerate(pax):
        if isinstance(p, dict) and "dob" not in p:
            problems.append(f"{row['booking_id']}/pax{i}: missing dob")

conn.close()

if problems:
